import { Colour, useDesignToken, useMaxWidthMediaQuery } from "@lifesg/react-design-system/theme";
import { PopoverTrigger } from "@lifesg/react-design-system/popover";
import { Typography } from "@lifesg/react-design-system/typography";
import { Card } from "@lifesg/react-design-system/card";
import { NavigationIcon } from "@lifesg/react-icons/navigation";
import { NavigationFillIcon } from "@lifesg/react-icons/navigation-fill";
import { ICircleFillIcon } from "@lifesg/react-icons";
import { PinFillIcon } from "@lifesg/react-icons/pin-fill";
import clsx from "clsx";
import * as L from "leaflet";
import "leaflet/dist/leaflet.css";
import { useEffect, useRef } from "react";
import ReactDOMServer from "react-dom/server";
import { TestHelper } from "../../../../../utils";
import { useFieldEvent } from "../../../../../utils/hooks";
import { LocationHelper } from "../../location-helper";
import { ILocationCoord } from "../../types";
import { markerFrom, removeMarkers } from "./helper";
import { Legend } from "./legend";
import * as styles from "./location-picker.styles";
import { ILocationPickerProps, IMapPin } from "./types";

// Show picker when
// tablet: "map" mode
// desktop : always on "double" mode
// Hide when tablet: "search" mode
export const LocationPicker = ({
	id = "location-picker",
	className,
	customClassName,
	mapPanZoom,
	panelInputMode,
	showLocationModal,
	selectedLocationCoord,
	interactiveMapPinIconUrl,
	getCurrentLocation,
	locationAvailable,
	gettingCurrentLocation,
	onMapCenterChange,
	mapBannerText,
	disableSelectionFromMap,
	disableSelectedLocationMarker,
	selectablePins,
	pinsOnlyIndicateCurrentLocation,
	currentLocation,
	legendItems,
	defaultAddress,
}: ILocationPickerProps) => {
	// =============================================================================
	// CONST, STATE, REFS
	// =============================================================================
	const mapRef = useRef<L.Map>();

	const leafletWrapperRef = useRef<HTMLDivElement>(null);
	const markersRef = useRef<L.Marker[]>();
	const legendTriggerRef = useRef<HTMLButtonElement>(null);
	const isMobile = useMaxWidthMediaQuery("lg");
	const iconPrimaryColor = useDesignToken(Colour["icon-primary"]);
	const leafletConfig: L.MapOptions = {
		minZoom: 11,
		maxZoom: isMobile ? 20 : 19,
	};

	const { dispatchFieldEvent } = useFieldEvent();

	// =============================================================================
	// EFFECTS
	// =============================================================================

	/**
	 * Attach map and keep ref
	 */
	useEffect(() => {
		/**
		 * If component has mounted and is in map mode OR double panel (location picker is alway on for double panel)
		 */
		if (leafletWrapperRef.current && showLocationModal) {
			if (!mapRef.current) {
				mapRef.current = L.map(leafletWrapperRef.current, { zoomControl: false });
				resetView();
				L.control
					.zoom({
						position: "bottomright",
					})
					.addTo(mapRef.current);
			}
			const basemap = L.tileLayer("https://www.onemap.gov.sg/maps/tiles/Default_HD/{z}/{x}/{y}.png", {
				detectRetina: true,
				maxNativeZoom: 18,
				maxZoom: mapPanZoom?.max ?? (isMobile ? 20 : 19),
				minZoom: leafletConfig.minZoom,
				// Do not remove this attribution
				attribution:
					'<div class="onemap"><img src="https://www.onemap.gov.sg/web-assets/images/logo/om_logo.png"/>&nbsp;<a href="https://www.onemap.gov.sg/" target="_blank" rel="noopener noreferrer">OneMap</a>&nbsp;&copy;&nbsp;contributors&nbsp;&#124;&nbsp;<a href="https://www.sla.gov.sg/" target="_blank" rel="noopener noreferrer">Singapore Land Authority</a></div>',
			});

			const [ne, sw] = LocationHelper.getMapBounds();
			mapRef.current.setMaxBounds(L.latLngBounds(L.latLng(ne), L.latLng(sw)));
			basemap.addTo(mapRef.current);

			// even if it didn't change, as it may have panned off-centre.
			if (!gettingCurrentLocation && selectedLocationCoord?.lat && selectedLocationCoord?.lng) {
				// NOTE: map will zoom when input is cleared in search panelInputMode and switches to map panelInputMode
				zoomWithMarkers([{ lat: selectedLocationCoord.lat, lng: selectedLocationCoord.lng }]);
			}
			const map = mapRef.current;

			// Reattach event listeners
			map.on("click", ({ latlng }: L.LeafletMouseEvent) => {
				if (!disableSelectionFromMap && !gettingCurrentLocation) {
					onMapCenterChange(latlng);
				}
			});

			map.on("zoomend", () => map.setMinZoom(mapPanZoom?.min ?? leafletConfig.minZoom));
		} else {
			if (mapRef.current) {
				mapRef.current?.off();
				mapRef.current?.remove();
				mapRef.current = undefined;
			}
		}
	}, [showLocationModal]);

	/**
	 * Centre map to selected location from search result
	 * Show the pan when we can see the map
	 */
	useEffect(() => {
		if (!selectedLocationCoord?.lat || !selectedLocationCoord?.lng) {
			// If there is no selected location, zoom to default address if available, else reset to default view
			if (defaultAddress?.lat && defaultAddress?.lng) {
				zoomWithMarkers([defaultAddress], false);
				return;
			}
			resetView();
			return;
		}

		if (selectablePins.length) {
			const pins = [...selectablePins];
			if (!disableSelectedLocationMarker) {
				pins.push(selectedLocationCoord);
			} else if (pinsOnlyIndicateCurrentLocation && currentLocation) {
				pins.push({ ...currentLocation, isCurrentLocation: true });
			}
			zoomWithMarkers(pins, true, selectedLocationCoord, true, true);
		} else {
			zoomWithMarkers([selectedLocationCoord], !disableSelectedLocationMarker);
		}
	}, [selectedLocationCoord?.lat, selectedLocationCoord?.lng, selectablePins, currentLocation]);

	// =============================================================================
	// HELPER FUNCTIONS
	// =============================================================================
	const resetView = () => {
		if (mapRef.current) {
			removeMarkers(markersRef.current);
			const center = L.bounds([1.56073, 104.11475], [1.16, 103.502]).getCenter();
			mapRef.current.setView([center.x, center.y], 12);
			setTimeout(() => mapRef.current?.invalidateSize(), 500);
		}
	};

	const zoomWithMarkers = (
		targets: IMapPin[],
		shouldSetMarkers = true,
		_zoomCenter?: ILocationCoord,
		selectableMarkers = false,
		enlargeSelectedMarker = false
	) => {
		const map = mapRef.current;
		if (!map) return;
		removeMarkers(markersRef.current);

		if (shouldSetMarkers) {
			markersRef.current = getMarkers(map, targets, selectableMarkers, enlargeSelectedMarker);
		}

		zoomAndCenter(map, _zoomCenter || targets[0]);
	};

	const getMarkers = (map: L.Map, targets: IMapPin[], shouldSelectOnClick: boolean, enlargeSelectedMarker: boolean) =>
		targets.map((target) => {
			const isSelected =
				enlargeSelectedMarker && !target.isCurrentLocation
					? target.lat === selectedLocationCoord.lat && target.lng === selectedLocationCoord.lng
					: undefined;
			const mapPinIcon =
				"data:image/svg+xml;base64," +
				btoa(ReactDOMServer.renderToString(<PinFillIcon color={iconPrimaryColor} />));
			const marker = markerFrom(
				target,
				interactiveMapPinIconUrl && !target.isCurrentLocation ? interactiveMapPinIconUrl : mapPinIcon,
				isSelected,
				target.isCurrentLocation
			).addTo(map);

			return shouldSelectOnClick && !target.isCurrentLocation
				? marker.on("click", () => {
						// To accurately identify the pin, use the original lat & lng from the pin
						// instead of the ones from the LeafletMouseEvent.
						zoomAndCenter(map, { lat: target.lat, lng: target.lng });
						onMapCenterChange({
							lat: target.lat,
							lng: target.lng,
						});
				  })
				: marker;
		});

	const zoomAndCenter = (map: L.Map, zoomCenter: ILocationCoord) => {
		const panZoomValue = Math.max(
			mapPanZoom?.min ?? leafletConfig.minZoom,
			isMobile ? mapPanZoom?.mobile ?? 18 : mapPanZoom?.nonMobile ?? 17
		);

		const zoomValue =
			map.getBounds().contains([zoomCenter.lat, zoomCenter.lng]) && map.getZoom() > panZoomValue
				? map.getZoom()
				: panZoomValue;

		map.flyTo(L.latLng(zoomCenter.lat, zoomCenter.lng), zoomValue, { duration: mapPanZoom?.duration });
		setTimeout(() => map.invalidateSize(), 500);
	};

	return (
		<div
			className={clsx(
				styles.locationPickerWrapper,
				className,
				customClassName && `${customClassName}-location-picker`
			)}
			id={TestHelper.generateId(id, "location-picker")}
			data-testid={TestHelper.generateId(id, "location-picker", panelInputMode === "search" ? "hide" : "show")}
			data-panel-mode={panelInputMode}
		>
			{mapBannerText && (
				<div className={styles.bannerWrapper} data-testid={TestHelper.generateId(id, "location-banner")}>
					<Card className={styles.banner}>
						<Typography.BodyXS>{mapBannerText}</Typography.BodyXS>
					</Card>
				</div>
			)}
			<div className={styles.leafletWrapper} ref={leafletWrapperRef} />
			<button
				className={clsx(styles.button, styles.buttonLocation)}
				data-testid={TestHelper.generateId(id, "refresh-current-location-button")}
				aria-label="Refresh current location"
				onClick={() => {
					if (locationAvailable) {
						const shouldPreventDefault = !dispatchFieldEvent("click-refresh-current-location", id);
						if (!shouldPreventDefault) {
							if (defaultAddress?.lat && defaultAddress?.lng) {
								zoomWithMarkers([defaultAddress], false);
								return;
							}
							getCurrentLocation();
						}
					}
				}}
			>
				<span className={styles.buttonLocationImage}>
					{locationAvailable ? <NavigationFillIcon /> : <NavigationIcon />}
				</span>
			</button>
			{legendItems && legendItems.length > 0 && (
				<PopoverTrigger
					popoverContent={() => {
						const handleClose = () => {
							// Click the trigger button to close the popover
							legendTriggerRef.current?.click();
						};
						return <Legend id={id} onClose={handleClose} items={legendItems} />;
					}}
					isModal={false}
				>
					<button
						ref={legendTriggerRef}
						className={clsx(styles.button, styles.buttonLegend)}
						data-testid={TestHelper.generateId(id, "legend-trigger")}
						aria-label="Toggle legend"
					>
						<span className={styles.buttonLocationImage}>
							<ICircleFillIcon />
						</span>
					</button>
				</PopoverTrigger>
			)}
		</div>
	);
};
